function settings(){return title('10 / CREDENTIALS','Provider credentials','Configure GitHub Actions secrets without exposing keys in your Pages deployment.')+`<div class="panel credential-intro"><div class="panelheading"><h3>Private by design</h3><span class="pill unverified" id="bridge-label">Checking local companion…</span></div><p class="muted">Keys never enter your Basis study, browser storage, export, or repository. To submit them, open this app through the optional local companion, authenticated with GitHub CLI. On GitHub Pages, the fields remain disabled.</p><div class="credential-actions"><a href="https://cli.github.com/manual/gh_auth_login" target="_blank" rel="noopener noreferrer">GitHub CLI setup ↗</a><button class="secondary" type="button" id="bridge-recheck">Check connection</button></div><p class="tiny">Start locally: <code>python3 scripts/credential_companion.py</code>. Then open the printed localhost address. Run <code>gh auth login</code> beforehand.</p></div><div class="panel"><div class="panelheading"><h3>GitHub destination</h3><span class="miniTag">Actions repository secrets</span></div><label class="credentials-repo-label">Repository (owner/repo)<input id="secret-repo" autocomplete="off" spellcheck="false" placeholder="organization/basis-evaluation" maxlength="100" /></label><p class="panelnote">Use the private evaluation runner repository, not a public source repository for results.</p></div><div class="credential-list">${secretProviders.map(p=>`<div class="panel credential-card"><div class="credential-head"><div><strong>${esc(p.name)}</strong><small>${esc(p.hint)}</small></div><span class="credential-indicator">${p.secret?'Not verified':'Uses provider keys'}</span></div>${p.secret?`<label class="credentials-key-label" for="key-${p.id}">${esc(p.secret)}</label><div class="credential-form"><input type="password" id="key-${p.id}" data-secret-input autocomplete="new-password" disabled placeholder="Start local companion to enter key" aria-label="${esc(p.name)} secret" /><button class="secondary" data-secret-toggle="${p.id}" disabled type="button">Show</button><button class="primary" data-secret-save="${p.id}" disabled type="button">Save securely</button></div><p class="credential-feedback" id="result-${p.id}" role="status" aria-live="polite"></p>`:`<p class="muted">Choose a model provider in the execution workflow and configure its corresponding key above.</p>`}</div>`).join('')}</div><div class="panelnote">GitHub encrypts Actions secrets at rest; after submission the site cannot read the stored values. Connection health does not reveal which secrets exist. Only the four implemented runners can execute today.</div>`;}
let bridgeReady=false;let bridgeToken='';
async function checkBridge(){const label=$('#bridge-label');if(!label)return;bridgeReady=false;bridgeToken='';try{if(!['localhost','127.0.0.1'].includes(location.hostname))throw Error('Not running locally');let r=await fetch('/api/health',{cache:'no-store'});let j=await r.json();if(!r.ok||j.service!=='basis-credential-companion'||typeof j.token!=='string')throw Error('Unavailable');bridgeReady=true;bridgeToken=j.token;}catch{}label.textContent=bridgeReady?'Local companion connected':'Open via local companion';label.className='pill '+(bridgeReady?'pass':'unverified');document.querySelectorAll('[data-secret-input],[data-secret-save],[data-secret-toggle]').forEach(e=>e.disabled=!bridgeReady);}
async function submitSecret(id){const p=secretProviders.find(x=>x.id===id);if(!p?.secret||!bridgeReady)return;const input=$('#key-'+id),out=$('#result-'+id),repo=$('#secret-repo')?.value.trim();if(!/^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/.test(repo||'')){out.textContent='Enter a valid owner/repo first.';return}if(!input.value||/[\r\n]/.test(input.value)){out.textContent='Enter a single-line API key.';return}const value=input.value;input.value='';out.textContent='Submitting to GitHub Actions Secrets…';try{const res=await fetch('/api/secrets',{method:'POST',headers:{'Content-Type':'application/json','X-Basis-Token':bridgeToken},body:JSON.stringify({repo,secret:p.secret,value})});const json=await res.json();out.textContent=res.ok?'Saved to GitHub Actions Secrets. Value is no longer accessible here.':(json.error||'Unable to save.');}catch{out.textContent='Local companion unavailable. The key was not retained.'}}
function bindCredentials(){checkBridge();$('#bridge-recheck')?.addEventListener('click',checkBridge);document.querySelectorAll('[data-secret-save]').forEach(b=>b.addEventListener('click',()=>submitSecret(b.dataset.secretSave)));document.querySelectorAll('[data-secret-toggle]').forEach(b=>b.addEventListener('click',()=>{let input=$('#key-'+b.dataset.secretToggle);if(input.type==='password'){input.type='text';b.textContent='Hide'}else{input.type='password';b.textContent='Show'}}));}
function benchmarks(){
 let rows=[];try{rows=JSON.parse(localStorage.getItem('basis-community-benchmark-imports')||'[]')}catch{}
 const config=JSON.parse(localStorage.getItem('basis-swe-config')||'{"percent":10,"seed":"42","agents":["codex"]}');
 const opts=[5,10,25,50,100].map(v=>`<button type="button" data-swe-pct="${v}" class="${config.percent===v?'active':''}">${v===100?'Full · 300':v+'% · '+Math.ceil(v*3)}</button>`).join('');
 const agentOptions=['codex','claude','cursor','opencode'].map(a=>`<label class="swe-agent"><input type="checkbox" data-swe-agent="${a}" ${config.agents.includes(a)?'checked':''}> ${a==='codex'?'Codex':a==='claude'?'Claude Code':a==='cursor'?'Cursor':'OpenCode'}</label>`).join('');
 const box=`<section class="panel swe-studio"><div class="panelheading"><h3>${icon('flask',18)} SWE-bench Lite · Run studio</h3><span class="miniTag">Official test split · 300 tasks</span></div><p class="muted">1 · Choose a reproducible sample. 2 · Select agents. 3 · Launch in GitHub Actions. 4 · Import genuine official-harness results.</p><div class="swe-columns"><div><label class="swe-label">Sample size</label><div class="pillgroup swe-preset">${opts}</div><label class="swe-label" for="swe-custom">Custom percentage</label><input id="swe-custom" type="number" min="1" max="100" step="1" value="${config.percent}"><p class="panelnote" id="swe-count">${Math.ceil(config.percent*3)} of 300 tasks · repo-balanced nested sample</p><label class="swe-label" for="swe-seed">Random seed</label><input id="swe-seed" maxlength="40" value="${esc(config.seed)}" aria-label="Random seed"><p class="panelnote">The same seed gives every agent the same selected tasks. Larger percentages include the smaller sample.</p></div><div><label class="swe-label">Coding agents</label><div class="swe-agents">${agentOptions}</div><p class="panelnote">Provider credentials are configured in Settings. API usage and Docker grading may incur significant costs.</p><label class="swe-label" for="swe-repo">Evaluation repository</label><input id="swe-repo" placeholder="owner/repository" value="${esc(config.repo||'')}" autocomplete="off" spellcheck="false"><div class="bench-actions"><button class="primary" data-act="open-swe-actions">${icon('play',16)} Open GitHub Actions ↗</button><button class="secondary" data-act="download-swe-config">${icon('download',16)} Download run configuration</button></div><p class="panelnote" id="swe-guidance">GitHub Pages cannot securely start paid runners directly. The workflow launches from GitHub Actions using the same selections.</p></div></div></section>`;
 return title('08 / COMMUNITY BENCHMARKS','Benchmark library','Standard, externally maintained suites. Pick a benchmark, run its official harness, and bring the evidence back to Basis.')+box+
 `<div class="benchmark-grid">${BENCHMARKS.map((b,i)=>`<article class="panel benchmark-tile"><div class="panelheading"><h3>${esc(b.name)}</h3><span class="miniTag">Official suite</span></div><div class="muted">${esc(b.category)} · ${esc(b.difficulty)}</div><p>${esc(b.note)}</p><div class="panelnote">${esc(b.runner)}<br>${esc(b.runtime)}</div><div class="bench-actions"><a href="${b.setup}" target="_blank" rel="noopener noreferrer" class="secondary">Run instructions ↗</a><a href="${b.source}" target="_blank" rel="noopener noreferrer" class="textaction" aria-label="Official source ${esc(b.name)}">Source ↗</a></div></article>`).join('')}</div>`+
 `<div class="panel"><div class="panelheading"><h3>Import standardized evidence</h3><span class="miniTag">Not automatically verified</span></div><p class="muted">Run the official benchmark harness externally; normalize its authentic task outcomes to the Basis v1 report schema. Importing does not certify that the claimed agent or harness was used.</p><div class="bench-actions"><button class="primary" data-act="import-benchmark">${icon('upload',16)} Import benchmark report</button><button class="secondary" data-act="download-benchmark-template">${icon('download',16)} Download report template</button></div><input type="file" id="benchmark-file" accept="application/json,.json" hidden><div class="panelnote">Scores are only comparable for exactly matching dataset revisions, harness revisions, evaluation conditions and task sets. Existing toy-agent runs are not community benchmark runs.</div></div>`+
 (rows.length?`<div class="panel"><div class="panelheading"><h3>Imported reports</h3><span class="miniTag">Self-reported · Unverified</span></div><div class="table-scroll"><table><thead><tr><th>Benchmark</th><th>Agent / model</th><th>Resolved</th><th>Tasks</th><th>Evidence</th></tr></thead><tbody>${rows.map(r=>{const sum=summarizeReport(r);return `<tr><td>${esc(BENCHMARKS.find(b=>b.id===r.benchmarkId)?.name)}</td><td>${esc(r.agent)} / ${esc(r.model)}</td><td>${sum.resolved} / ${sum.total}</td><td>${sum.total}</td><td>Unverified import</td></tr>`}).join('')}</tbody></table></div></div>`:`<div class="panel"><p class="muted">No benchmark results imported yet. No fabricated scores are shown.</p></div>`);
}
const views={overview,org,gates,pilot,compare,technology,execution,benchmarks,judge,decision:decisionPage,settings};function render(){document.title=`Basis · ${nav.find(x=>x[0]===page)?.[1]}`;$('#app').innerHTML=shell(views[page]());bind();if(page==='settings')bindCredentials();}
function setPath(path,value){let [a,b]=path.split('.');if(a==='meta')s.meta[b]=value;else if(a==='org'){s.org[b]=b==='stack'?value.split(',').map(x=>x.trim()).filter(Boolean):['rate','budget','developers'].includes(b)?Number(value):value;}else if(a==='assumptions')s.assumptions[b]=Number(value);save();}
function addModal(name,fields,callback){const wrap=document.createElement('div');wrap.className='modalback';wrap.innerHTML=`<form class="modal"><div class="modalhead"><h2>${esc(name)}</h2><button type="button" class="iconbtn" data-close aria-label="Close">${icon('cross',18)}</button></div>${fields.map(x=>`<label>${x.label}${x.type==='select'?`<select name="${x.name}">${x.options.map(v=>`<option value="${esc(v[0])}">${esc(v[1])}</option>`).join('')}</select>`:x.type==='textarea'?`<textarea name="${x.name}" required></textarea>`:`<input name="${x.name}" type="${x.type||'text'}" ${x.required===false?'':'required'} ${x.min!=null?`min="${x.min}"`:''} value="${esc(x.value??'')}">`}</label>`).join('')}<div class="modalbuttons"><button type="button" data-close class="secondary">Cancel</button><button class="primary" type="submit">Save</button></div></form>`;document.body.append(wrap);wrap.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>wrap.remove());wrap.onclick=e=>{if(e.target===wrap)wrap.remove()};wrap.querySelector('form').onsubmit=e=>{e.preventDefault();const obj=Object.fromEntries(new FormData(e.target));callback(obj);wrap.remove();save();render();};wrap.querySelector('input,select,textarea')?.focus();}
function act(a,el){if(a==='menu'){drawer=!drawer;render()}else if(a==='import-benchmark'){$('#benchmark-file').click()}else if(a==='download-benchmark-template'){const data={type:'basis-community-benchmark-report',schemaVersion:1,benchmarkId:'swebench-lite',datasetRevision:'REPLACE_WITH_40_CHAR_COMMIT',harnessRevision:'REPLACE_WITH_40_CHAR_COMMIT',agent:'REPLACE',model:'REPLACE',executionMode:'CLI',runId:'REPLACE',provenance:'external-official-harness',verified:false,humanAccepted:false,tasks:[]};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const u=URL.createObjectURL(blob),l=document.createElement('a');l.href=u;l.download='basis-benchmark-report-template.json';l.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}else if(a==='import-agent'){$('#agent-file').click()}else if(a==='assistant'){addModal('Ask Basis · evaluation advisor',[{name:'q',label:'What would you like to understand?',type:'textarea'}],v=>{const q=v.q.toLowerCase(),d=decision(s),answer=q.includes('cost')?'Full cost includes human effort, tool usage and allocated platform overhead. The comparison lab lets you change labor assumptions.':q.includes('bias')||q.includes('judge')?'LLM judges may exhibit self-preference and order bias. Use blind, swapped comparisons, human calibration and deterministic gates.':q.includes('security')||q.includes('gate')?'Mandatory controls are defined in Governance. Unverified is not a pass; a failed gate blocks eligibility.':`Current status: ${d.heading}. ${d.reason} For a defensible choice, validate your organization profile, collect representative pilot results and verify controls.`;alert('Basis · local rules-based advisor\n\n'+answer+'\n\nNo live AI model is connected.');})}else if(a==='export'){const blob=new Blob([JSON.stringify(s,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),l=document.createElement('a');l.href=url;l.download='basis-study.json';l.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}else if(a==='import'){$('#file-input').click()}else if(a==='reset'){if(confirm('Start a new, empty study? This replaces your local data.')){s=clone(demo);selected='claude';save();note('Empty study created')}}else if(a==='manage-platforms'){addModal('Add coding platform',[{name:'name',label:'Platform name'},{name:'provider',label:'Provider / vendor'},{name:'mode',label:'Execution mode (IDE, CLI, autonomous, API)'},{name:'model',label:'Model/version under test'}],v=>{const id='p'+Date.now();s.platforms.push({id,...v,enabled:true});s.gateResults[id]={};})}else if(a==='clear-demo'){if(confirm('Remove all synthetic pilot runs? This cannot be undone without a saved export.')){s.runs=[];s.meta.demo=false;save();note('Synthetic results cleared; begin collecting actual evidence')}}else if(a==='add-task'){addModal('Add benchmark task',[{name:'name',label:'Task name'},{name:'type',label:'Work type',type:'select',options:TYPES.map(x=>[x,x])},{name:'difficulty',label:'Difficulty',type:'select',options:[['easy','Easy'],['medium','Medium'],['hard','Hard']]},{name:'acceptance',label:'Independent acceptance criteria'},{name:'baseline',label:'Baseline human minutes',type:'number',min:0,value:60}],v=>s.tasks.push({id:'T-'+Date.now().toString().slice(-7),...v,baseline:Number(v.baseline)}))}else if(a==='add-run'){addModal('Record a pilot result',[{name:'platform',label:'Platform',type:'select',options:s.platforms.map(x=>[x.id,x.name])},{name:'task',label:'Benchmark task',type:'select',options:s.tasks.map(x=>[x.id,x.name])},{name:'accepted',label:'Accepted by independent criteria?',type:'select',options:[['yes','Yes'],['no','No']]},{name:'humanMinutes',label:'Total human effort (minutes)',type:'number',min:0,value:60},{name:'usageCost',label:'Tool usage cost ($)',type:'number',min:0,value:5},{name:'evidence',label:'Evidence URL',required:false},{name:'notes',label:'Reviewer notes',type:'textarea',required:false}],v=>s.runs.push({id:'R-'+Date.now(),platform:v.platform,task:v.task,accepted:v.accepted==='yes',humanMinutes:Number(v.humanMinutes),usageCost:Number(v.usageCost),evidence:v.evidence,notes:v.notes,source:'Manual record',quality:v.accepted==='yes'?4:2,review:3,stability:3,date:new Date().toISOString().slice(0,10)}))}else if(a==='add-gate'){addModal('Add organization requirement',[{name:'name',label:'Required control'},{name:'required',label:'Classification',type:'select',options:[['yes','Mandatory'],['no','Advisory']]}],v=>s.gates.push({id:'g'+Date.now(),name:v.name,required:v.required==='yes'}))}else if(a==='add-judgment'){addModal('Add blind judge comparison',[{name:'caseName',label:'Masked evaluation case'},{name:'scoreA',label:'Independent judge A (1–5)',type:'number',min:1,value:3},{name:'scoreB',label:'Independent judge B (1–5)',type:'number',min:1,value:3},{name:'review',label:'Human reviewer outcome',required:false}],v=>s.judgments.push({id:'J'+Date.now(),caseName:v.caseName,scoreA:Number(v.scoreA),scoreB:Number(v.scoreB),review:v.review}))}else if(a==='delete-task'){if(confirm('Delete this task and its associated runs?')){s.tasks=s.tasks.filter(x=>x.id!==el.dataset.id);s.runs=s.runs.filter(x=>x.task!==el.dataset.id);save();render()}}else if(a==='delete-run'){if(confirm('Delete this result?')){s.runs=s.runs.filter(x=>x.id!==el.dataset.id);save();render()}}else if(a==='delete-gate'){if(confirm('Remove this requirement?')){s.gates=s.gates.filter(x=>x.id!==el.dataset.id);save();render()}}else if(a==='toggle-details'){details=!details;render()}else if(a==='mark-real'){alert('To create a real study, first choose Clear synthetic results in Pilot studio. Demonstration runs cannot be promoted to genuine evidence.');}}
function bind(){if(document.querySelector('.swe-studio')){
 const read=()=>{let pct=Number(document.querySelector('#swe-custom').value);if(!Number.isInteger(pct)||pct<1||pct>100)return null;const agents=[...document.querySelectorAll('[data-swe-agent]:checked')].map(x=>x.dataset.sweAgent);return {percent:pct,seed:document.querySelector('#swe-seed').value||'42',agents,repo:document.querySelector('#swe-repo').value.trim()}};
 const sync=()=>{let c=read();if(!c)return;localStorage.setItem('basis-swe-config',JSON.stringify(c));document.querySelector('#swe-count').textContent=`${Math.ceil(c.percent*3)} of 300 tasks · repo-balanced nested sample`;document.querySelectorAll('[data-swe-pct]').forEach(b=>b.classList.toggle('active',Number(b.dataset.swePct)===c.percent))};
 document.querySelectorAll('[data-swe-pct]').forEach(b=>b.onclick=()=>{document.querySelector('#swe-custom').value=b.dataset.swePct;sync()});
 document.querySelectorAll('.swe-studio input').forEach(el=>el.addEventListener('change',sync));
 document.querySelector('[data-act="open-swe-actions"]').onclick=()=>{const c=read();if(!c||!c.agents.length){alert('Select at least one agent and a valid sample percentage.');return}if(!/^[\w.-]+\/[\w.-]+$/.test(c.repo)){alert('Enter a valid GitHub repository owner/name.');return}sync();window.open(`https://github.com/${c.repo}/actions/workflows/swebench-lite.yml`,'_blank','noopener,noreferrer');document.querySelector('#swe-guidance').textContent=`In GitHub Actions choose Run workflow: percent=${c.percent}, seed=${c.seed}, agents=${c.agents.join(',')}. Confirm expected API and CI charges.`};
 document.querySelector('[data-act="download-swe-config"]').onclick=()=>{let c=read();if(!c||!c.agents.length){alert('Choose valid settings and at least one agent');return}const blob=new Blob([JSON.stringify({type:'basis-swebench-lite-run-config',...c},null,2)],{type:'application/json'});let u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='basis-swebench-lite-run.json';a.click();URL.revokeObjectURL(u)};
}document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{page=b.dataset.nav;drawer=false;render();window.scrollTo(0,0)});document.querySelectorAll('[data-act]').forEach(b=>b.onclick=()=>act(b.dataset.act,b));document.querySelectorAll('[data-sub]').forEach(b=>b.onclick=()=>{sub=b.dataset.sub;render()});document.querySelectorAll('[data-platform]').forEach(b=>b.onclick=()=>{selected=b.dataset.platform;render()});document.querySelectorAll('[data-path]').forEach(el=>el.onchange=()=>{setPath(el.dataset.path,el.value);render()});document.querySelectorAll('[data-weight]').forEach(el=>el.onchange=()=>{s.weights[el.dataset.weight]=Math.max(0,Number(el.value)||0);save();render()});document.querySelectorAll('[data-mix]').forEach(el=>el.oninput=()=>{s.mix[el.dataset.mix]=Number(el.value);save();$(`[data-mix-label="${el.dataset.mix}"]`).textContent=el.value+'%';$('#mixnote').textContent='Normalized for comparison: '+Object.values(s.mix).reduce((a,b)=>a+Number(b),0)+'% entered (automatically normalized).'});document.querySelectorAll('[data-gate]').forEach(el=>el.onchange=()=>{const [p,g]=el.dataset.gate.split(':');s.gateResults[p]??={};s.gateResults[p][g]=el.value;save();render()});document.querySelectorAll('[data-filter]').forEach(el=>el.onchange=()=>{filter=el.value;render()});document.querySelectorAll('[data-range]').forEach(el=>el.oninput=()=>{setPath(el.dataset.range,el.value);render()});if($('#benchmark-file'))$('#benchmark-file').onchange=async e=>{try{const r=validateBenchmarkReport(JSON.parse(await e.target.files[0].text()));let reports=JSON.parse(localStorage.getItem('basis-community-benchmark-imports')||'[]');reports=reports.filter(x=>!(x.benchmarkId===r.benchmarkId&&x.runId===r.runId&&x.agent===r.agent));reports.push(r);localStorage.setItem('basis-community-benchmark-imports',JSON.stringify(reports));note('Benchmark report imported — unverified provenance')}catch(err){alert('Cannot import benchmark report: '+err.message)}};if($('#agent-file'))$('#agent-file').onchange=async e=>{try{let r=JSON.parse(await e.target.files[0].text());if(r.provenance?.toLowerCase().includes('mock')||r.candidate==='mock')throw Error('Mock evidence is not permitted in production');if(r.type!=='basis-agent-evaluation'||r.schemaVersion!==2||!['claude','cursor','codex','opencode'].includes(r.candidate)||typeof r.automatedTestsPass!=='boolean'||r.accepted!==false||!/^([a-f0-9]{64})$/.test(r.taskDigest))throw Error('Unrecognized or invalid execution schema');localStorage.setItem('basis-latest-agent-result',JSON.stringify(r));note('Automated run imported: human review still required')}catch(err){alert('Cannot import: '+err.message)}};$('#file-input').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const data=JSON.parse(await file.text());if(!validateState(data))throw Error('Not a Basis study');if(data.meta?.demo||data.runs.some(r=>/illustrative|synthetic|mock/i.test([r.source,r.notes,r.recordKind,r.candidate].join(' '))))throw Error('Demonstration or mock data cannot be imported into production');if(!confirm('Replace the current workspace with the imported study?'))return;s=data;save();note('Study imported as user-provided, unverified evidence')}catch(err){alert('Import failed: '+err.message)}}}
render();
